  1104	  private static final class TrackingTransactionTemplate extends TransactionTemplate {
  1105	    private final DataSource source;
  1106	
  1107	    TrackingTransactionTemplate(DataSource source) {
  1108	      super(new DataSourceTransactionManager(source));
  1109	      this.source = source;
  1110	    }
  1111	
  1112	    @Override
  1113	    public <T> T execute(TransactionCallback<T> callback) {
  1114	      SourceStopOwner owner = SourceStopOwner.CONFIRMATION.get();
  1115	      if (owner == null) {
  1116	        return super.execute(callback);
  1117	      }
  1118	      try {
  1119	        assertThat(owner.source).isSameAs(source);
  1120	        assertThat(owner.executingThread).isSameAs(Thread.currentThread());
  1121	        assertThat(owner.finished.get()).isEqualTo(1);
  1122	        assertThat(owner.confirmationCalls.incrementAndGet()).isEqualTo(1);
  1123	        if (owner.gateConfirmation) {
  1124	          owner.confirmationGate.hold();
  1125	        }
  1126	        // Original callback, original manager/source, actual commit/resource cleanup, exactly once.
  1127	        return super.execute(callback);
  1128	      } catch (RuntimeException | Error failure) {
  1129	        owner.failure.compareAndSet(null, failure);
  1130	        throw failure;
  1131	      } finally {
  1132	        SourceStopOwner.CONFIRMATION.remove();
  1133	        owner.completed.countDown();
  1134	      }
  1135	    }
  1136	  }
