  1148	            return;
  1149	          } catch (InterruptedException interruption) {
  1150	            interrupted = true;
  1151	          }
  1152	        }
  1153	      } finally {
  1154	        if (interrupted) {
  1155	          Thread.currentThread().interrupt();
  1156	        }
  1157	      }
  1158	    }
  1159	
  1160	    void release() {
  1161	      released.countDown();
  1162	    }
  1163	  }
