  1433	  /** Opaque bidirectional JDBC traffic only; no bodies, credentials or authority are recorded. */
  1434	  private static final class PrivatePgRoute implements AutoCloseable {
  1435	    private final InetSocketAddress target;
  1436	    private final List<SourceStopOwner> owners = new java.util.concurrent.CopyOnWriteArrayList<>();
  1437	
  1438	    void attach(SourceStopOwner owner) {
  1439	      owners.add(owner);
  1440	    }
  1441	    private final ExecutorService bridges = Executors.newVirtualThreadPerTaskExecutor();
  1442	    private final Set<java.net.Socket> sockets = ConcurrentHashMap.newKeySet();
  1443	    private final AtomicInteger activeTransfers = new AtomicInteger();
  1444	    private final java.util.Queue<IOException> closeFailures =
  1445	        new java.util.concurrent.ConcurrentLinkedQueue<>();
  1446	    private volatile java.net.ServerSocket listener;
  1447	    private int privatePort;
  1448	    private boolean closed;
  1449	
  1450	    PrivatePgRoute(String host, int port) throws IOException {
  1451	      target = new InetSocketAddress(host, port);
  1452	      try {
  1453	        reopen();
  1454	      } catch (IOException | RuntimeException | Error failure) {
  1455	        bridges.shutdownNow();
  1456	        throw failure;
  1457	      }
  1458	    }
  1459	
  1460	    synchronized int port() {
  1461	      return privatePort;
  1462	    }
  1463	
  1464	    synchronized void reopen() throws IOException {
  1465	      if (closed) {
  1466	        throw new IOException("Case-owned PG route is closed");
  1467	      }
  1468	      if (listener != null && !listener.isClosed()) {
  1469	        return;
  1470	      }
  1471	      var server = new java.net.ServerSocket();
  1472	      try {
  1473	        server.setReuseAddress(true);
  1474	        server.bind(new InetSocketAddress("127.0.0.1", privatePort));
  1475	        privatePort = server.getLocalPort();
  1476	        listener = server;
  1477	        bridges.submit(() -> accept(server));
  1478	      } catch (IOException | RuntimeException | Error failure) {
  1479	        try {
  1480	          server.close();
  1481	        } catch (IOException cleanupFailure) {
  1482	          failure.addSuppressed(cleanupFailure);
  1483	        }
  1484	        // Retain a failed-close listener so final cleanup can account for its ownership.
  1485	        listener = server.isClosed() ? null : server;
  1486	        throw failure;
  1487	      }
  1488	    }
  1489	
  1490	    private void accept(java.net.ServerSocket server) {
  1491	      while (!server.isClosed()) {
  1492	        java.net.Socket application = null;
  1493	        java.net.Socket database = null;
  1494	        try {
  1495	          application = server.accept();
  1496	          sockets.add(application);
  1497	          if (server.isClosed()) {
  1498	            closeSocket(application);
  1499	            return;
  1500	          }
  1501	          database = new java.net.Socket();
  1502	          sockets.add(database);
  1503	          database.connect(target, 3000);
  1504	          if (server.isClosed()) {
  1505	            closeSocket(application);
  1506	            closeSocket(database);
  1507	            return;
  1508	          }
  1509	          java.net.Socket app = application, pg = database;
  1510	          beginTransfer(app, pg);
  1511	          beginTransfer(pg, app);
  1512	        } catch (IOException | java.util.concurrent.RejectedExecutionException failure) {
  1513	          closeSocket(application);
  1514	          closeSocket(database);
  1515	          if (server.isClosed()) {
  1516	            return;
  1517	          }
  1518	        }
  1519	      }
  1520	    }
  1521	
  1522	    boolean idle() {
  1523	      return activeTransfers.get() == 0 && sockets.isEmpty();
  1524	    }
  1525	
  1526	    private void beginTransfer(java.net.Socket from, java.net.Socket to) {
  1527	      activeTransfers.incrementAndGet();
  1528	      try {
  1529	        bridges.submit(() -> transfer(from, to));
  1530	      } catch (java.util.concurrent.RejectedExecutionException failure) {
  1531	        activeTransfers.decrementAndGet();
  1532	        throw failure;
  1533	      }
  1534	    }
  1535	
  1536	    private void transfer(java.net.Socket from, java.net.Socket to) {
  1537	      byte[] bytes = new byte[8192];
  1538	      try {
  1539	        int count;
  1540	        while ((count = from.getInputStream().read(bytes)) != -1) {
  1541	          to.getOutputStream().write(bytes, 0, count);
  1542	          to.getOutputStream().flush();
  1543	        }
  1544	      } catch (IOException disconnected) {
  1545	        // JDBC completion and the explicit private route cut close both opaque sides.
  1546	      } finally {
  1547	        Arrays.fill(bytes, (byte) 0);
  1548	        try {
  1549	          closeSocket(from);
  1550	          closeSocket(to);
  1551	        } finally {
  1552	          activeTransfers.decrementAndGet();
  1553	        }
  1554	      }
  1555	    }
  1556	
  1557	    private void closeSocket(java.net.Socket socket) {
  1558	      if (socket == null) {
  1559	        return;
  1560	      }
  1561	      try {
  1562	        socket.close();
  1563	      } catch (IOException failure) {
  1564	        closeFailures.add(failure);
  1565	      } finally {
  1566	        if (socket.isClosed()) {
  1567	          sockets.remove(socket);
  1568	        }
  1569	      }
  1570	    }
  1571	
  1572	    synchronized void unavailable() throws IOException {
  1573	      IOException listenerFailure = null;
  1574	      java.net.ServerSocket previous = listener;
  1575	      listener = null;
  1576	      if (previous != null) {
  1577	        try {
  1578	          previous.close();
  1579	        } catch (IOException failure) {
  1580	          listenerFailure = failure;
  1581	          if (!previous.isClosed()) {
  1582	            listener = previous;
  1583	          }
  1584	        }
  1585	      }
  1586	      // Continue socket cleanup even if closing the listener failed.
  1587	      for (var socket : sockets.toArray(java.net.Socket[]::new)) {
  1588	        closeSocket(socket);
  1589	      }
  1590	      if (listenerFailure != null) {
  1591	        throw listenerFailure;
  1592	      }
  1593	    }
  1594	
  1595	    @Override
  1596	    public void close() throws Exception {
  1597	      // Observation failures never authorize closing beneath the real sender/confirmation.
  1598	      for (SourceStopOwner owner : owners) {
  1599	        owner.drainUninterruptibly();
  1600	      }
  1601	      var failures = new java.util.ArrayList<Throwable>();
  1602	      synchronized (this) {
  1603	        closed = true;
  1604	        try {
  1605	          unavailable();
  1606	        } catch (Exception | Error failure) {
  1607	          failures.add(failure);
  1608	        }
